using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class TruceConfirmationTests
{
    static readonly EntityId Home=new("site:kofu"),Owner=new("org:takeda"),Other=new("org:oda"),Old=new("person:shingen"),Opponent=new("person:nobunaga"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id;
    static readonly Lazy<ContractWorld> Ready=new(Create);
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static void At(WorldSession s,long t){while(s.Seconds<t){var n=s.Seconds;s.SetPaused(false);s.AdvanceTo(t,100000);Assert.True(s.Seconds>n);}}
    static long Arrival(WorldSession s,string message)=>s.DiagnosticSnapshot().Couriers!.Missions.Single(c=>s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==c.Attempt&&a.MessageId==message)).ReadyAt;
    static ContractWorld Create()=>CreateCore(true);
    static ContractWorld CreateCore(bool read){var s=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],Old.Value,42,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy,trucePolicy:TruceNegotiations.Policy));Good(s.NegotiateTruce(new(new("request:confirmation-original-proposal"),TruceAction.Propose,Owner,Other,Days:30),Old,s.Revision));var offer=s.DiagnosticSnapshot().Truces!.Papers.Single();At(s,Arrival(s,offer.Message)+1);var accept=s.DiagnosticSnapshot().Truces!.Papers.Single(p=>p.Input.Action==TruceAction.Accept);At(s,Arrival(s,accept.Message));var succession=new EntityId("request:confirmation-succession");Good(s.ManageHouseSuccession(new(succession,HouseSuccessionAction.Nominate,Owner,Heir),Old,s.Revision));Good(s.ManageHouseSuccession(new(new("request:confirmation-head-consent"),HouseSuccessionAction.Confirm,Owner,Original:succession),Old,s.Revision));At(s,s.Seconds+1);Good(s.Open(Old,new(accept.Message),s.Revision));if(read)Good(s.ReadInheritedTruce(new(new("request:confirmation-inherited-read"),Owner,accept.Input.Id),Old,s.Revision));s.SetPaused(true);return s.DiagnosticSnapshot();}
    static WorldSession Start()=>new(ContractJson.Copy(Ready.Value));
    static EntityId Acceptance(WorldSession s)=>s.DiagnosticSnapshot().Truces!.Formations.Single().Acceptance;
    static TruceConfirmationInput Input(WorldSession s,TruceConfirmationAction action=TruceConfirmationAction.Send,string? original=null)=>new(new("request:confirmation-test/"+s.Revision),action,Owner,Acceptance(s),original);
    static TruceConfirmationPaper Send(WorldSession s){Good(s.SendTruceConfirmation(Input(s),Old,s.Revision));return s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.Confirmation);}
    static TruceConfirmationPaper Receipt(WorldSession s)=>s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.Receipt);
    static TruceConfirmationPaper FailAndReport(WorldSession s,TruceConfirmationPaper p,bool open=true){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,p.Id));At(s,Arrival(s,p.Id)+2);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id));At(s,Arrival(s,f.Id)+1);var notices=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Where(n=>n.Kind==TruceConfirmationKind.FailureNotice&&n.Related==p.Id).ToArray();Assert.True(notices.Length==1,System.Text.Json.JsonSerializer.Serialize(new{Time=s.Seconds,Confirm=s.DiagnosticSnapshot().TruceConfirmations,Attempts=s.DiagnosticSnapshot().Messaging.Attempts,Known=s.DiagnosticSnapshot().Messaging.Knowledge}));var notice=notices.Single();At(s,Arrival(s,notice.Id)+1);if(open)Good(s.Open(Old,new(notice.Id),s.Revision));return notice;}
    [Fact]public void ActualHeadSignsSeparatePaperWhileRetiredRequesterOwnsTheReturnAddress(){var s=Start();var before=s.DiagnosticSnapshot();var p=Send(s);Assert.Equal(Heir,p.Sender);Assert.Equal(Old,p.Requester);Assert.Equal(Opponent,p.Recipient);Assert.Equal(Heir,p.Authority!.Issuer);Assert.Equal(Home,p.ReturnAddress);Assert.Equal(ContractJson.Write(before.Truces),ContractJson.Write(s.DiagnosticSnapshot().Truces));Assert.Equal(ContractJson.Write(before.ResourceLots),ContractJson.Write(s.DiagnosticSnapshot().ResourceLots));Assert.Empty(TruceNegotiations.Known(s.DiagnosticSnapshot(),Opponent));Assert.Contains("未確認",s.TruceConfirmationView().Sent.Single().Status);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void PhysicalOpeningChangesOnlyRecipientKnowledgeAndReceiptStillMustTravel(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id)-1);Assert.Empty(TruceNegotiations.Known(s.DiagnosticSnapshot(),Opponent));At(s,Arrival(s,p.Id));Assert.Single(TruceNegotiations.Known(s.DiagnosticSnapshot(),Opponent));var receipt=Receipt(s);Assert.Equal(Opponent,receipt.Sender);Assert.Equal(Old,receipt.Recipient);Assert.Equal(p.Terms,receipt.Terms);Assert.Equal(p.Id,receipt.Related);Assert.Equal(Arrival(s,p.Id),receipt.ObservedAt);Assert.Empty(s.TruceConfirmationView().Reports);At(s,Arrival(s,receipt.Id));Assert.Contains("未確認",s.TruceConfirmationView().Sent.Single().Status);Good(s.Open(Old,new(receipt.Id),s.Revision));Assert.Contains("返報を確認",s.TruceConfirmationView().Sent.Single().Status);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void FailureKnowledgeTravelsFirstToSignerThenToRequester(){var s=Start();var p=Send(s);var n=FailAndReport(s,p,false);Assert.Equal(Heir,n.Sender);Assert.Equal(Old,n.Recipient);Assert.Empty(s.TruceConfirmationView().Sent.Single().Retryable);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision).Code);Good(s.Open(Old,new(n.Id),s.Revision));Assert.Contains(p.Id,s.TruceConfirmationView().Sent.Single().Retryable);Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision));var copies=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Where(p=>p.Kind==TruceConfirmationKind.Confirmation).ToArray();Assert.Equal(copies[0].Terms,copies[1].Terms);Assert.Equal(copies[0].Recipient,copies[1].Recipient);Assert.Equal(copies[0].Address,copies[1].Address);Assert.Equal(copies[0].Id,copies[1].CopyOf);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void LostFailureRelayDoesNotPermitAnUninformedResend(){var s=Start();var p=Send(s);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,p.Id));At(s,Arrival(s,p.Id)+2);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id));At(s,Arrival(s,f.Id));var n=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.FailureNotice);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,n.Id));At(s,Arrival(s,n.Id)+2);Assert.Empty(s.TruceConfirmationView().Sent.Single().Retryable);Assert.Empty(s.TruceConfirmationView().Reports);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision).Code);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void CopiesAreBoundedToThreeAndDoNotCreateAnotherTruce(){var s=Start();var p=Send(s);FailAndReport(s,p);Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision));var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Confirmation);FailAndReport(s,copy);Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,copy.Id),Old,s.Revision));Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision).Code);Assert.Equal(3,s.DiagnosticSnapshot().TruceConfirmations!.Papers.Count(p=>p.Kind==TruceConfirmationKind.Confirmation));Assert.Single(s.DiagnosticSnapshot().Truces!.Formations);}
    [Theory][InlineData(false)][InlineData(true)]public void PhysicallyRecoveredOriginalAndRetryDoNotRepeatReceiptOrFulfillment(bool originalFirst){var s=Start();var p=Send(s);FailAndReport(s,p);Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision));var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Confirmation);if(!originalFirst)At(s,Arrival(s,copy.Id));s.DiagnosticRecoverLocalCourier(p.Id,1);At(s,s.Seconds+1);if(originalFirst)At(s,Arrival(s,copy.Id));var w=s.DiagnosticSnapshot();Assert.Equal(2,w.Messaging.Attempts.Count(a=>new[]{p.Id,copy.Id}.Contains(a.MessageId)&&a.Status==AttemptStatus.Delivered));Assert.Single(w.TruceConfirmations!.Papers,p=>p.Kind==TruceConfirmationKind.Receipt);Assert.Single(w.Truces!.Fulfillments,f=>f.Actor==Opponent);Assert.Single(TruceNegotiations.Known(w,Opponent));new WorldSession(w);}
    [Fact]public void TimerOnlyLateArrivalCannotReplacePhysicalRecovery(){var s=Start();var p=Send(s);FailAndReport(s,p);Assert.Throws<InvalidDataException>(()=>s.DiagnosticTransport((m,t)=>MessageFlow.ScheduleLate(m,p.Id,1,t,2)));}
    [Fact]public void DuplicateWrongActorConflictAndStaleViewDoNotDuplicatePaper(){var s=Start();var i=Input(s);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(i,Heir,s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.SendTruceConfirmation(i,Old,s.Revision-1).Code);Good(s.SendTruceConfirmation(i,Old,s.Revision));Assert.Equal(ResultCode.AlreadyAccepted,s.SendTruceConfirmation(i,Old,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.SendTruceConfirmation(i with{Owner=Other},Old,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s),Old,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers);}
    [Fact]public void RequesterAwayCannotAskAnAbsentSignerToSendOrResend(){var s=Start();Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:confirmation-away","castle"),s.Revision));At(s,s.Seconds+2);Assert.Empty(s.TruceConfirmationCandidates());Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s),Old,s.Revision).Code);Assert.Null(s.DiagnosticSnapshot().TruceConfirmations);}
    [Fact]public void ExpiredOriginalDoesNotBecomeANewAgreementByConfirmation(){var s=Start();var until=s.DiagnosticSnapshot().Truces!.Formations.Single().Terms.Until;At(s,until);Assert.Empty(s.TruceConfirmationCandidates());Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s),Old,s.Revision).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ForgedSignerRecipientTermsRequesterOrAuthorityCannotLoad(int n){var s=Start();Send(s);var w=s.DiagnosticSnapshot();var p=w.TruceConfirmations!.Papers[0];w.TruceConfirmations.Papers[0]=n switch{0=>p with{Sender=Old},1=>p with{Recipient=Heir},2=>p with{Terms=p.Terms with{Until=p.Terms.Until+1}},3=>p with{Requester=Heir},_=>p with{Authority=p.Authority! with{Issuer=Old}}};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData("Papers")][InlineData("FailureOpenings")][InlineData("Entries")]public void OptionalWorldStateDoesNotRelaxRequiredStateFields(string field){var s=Start();Send(s);var n=System.Text.Json.Nodes.JsonNode.Parse(ContractJson.Write(s.DiagnosticSnapshot()))!;n["TruceConfirmations"]!.AsObject().Remove(field);Assert.Throws<InvalidDataException>(()=>ContractJson.Read<ContractWorld>(System.Text.Encoding.UTF8.GetBytes(n.ToJsonString())));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void ActualGenerationRecoveryAndFutureKeepPaperKnowledgeAndPositions(int phase){var s=Start();TruceConfirmationPaper? p=null;if(phase>0)p=Send(s);if(phase is 2 or 3){At(s,Arrival(s,p!.Id));if(phase==3){var r=Receipt(s);At(s,Arrival(s,r.Id));Good(s.Open(Old,new(r.Id),s.Revision));}}if(phase>=4){FailAndReport(s,p!,phase!=4);if(phase>=6){Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p!.Id),Old,s.Revision));if(phase==7){var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Confirmation);At(s,Arrival(s,copy.Id));s.DiagnosticRecoverLocalCourier(p.Id,1);At(s,s.Seconds+1);}}}Save(s,"truce-confirmation-"+phase);}
    static void Save(WorldSession s,string name){s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"truce-confirmation-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"confirmation",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("confirmation"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(s.TruceConfirmationView()),ContractJson.Write(b.TruceConfirmationView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,name+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,name+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var x in new[]{s,b})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}

    [Fact]public void NoSuccessorSignatureCanBorrowAnUnshownOriginal(){var s=new WorldSession(CreateCore(false));Assert.Empty(s.TruceConfirmationCandidates());Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s),Old,s.Revision).Code);Assert.Null(s.DiagnosticSnapshot().TruceConfirmations);}
    [Fact]public void KnownReceiptStopsAResendEvenWhenAnOldFailureIsKnown(){var s=Start();var p=Send(s);FailAndReport(s,p);Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision));var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Confirmation);At(s,Arrival(s,copy.Id));var receipt=Receipt(s);At(s,Arrival(s,receipt.Id));Good(s.Open(Old,new(receipt.Id),s.Revision));Assert.Empty(s.TruceConfirmationView().Sent.Single().Retryable);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision).Code);}
    [Fact]public void KnownFailureRemainsKnownWhileRequesterTravelsButLocalSignerIsStillRequired(){var s=Start();var p=Send(s);FailAndReport(s,p);Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:known-failure-away","castle"),s.Revision));At(s,s.Seconds+2);Assert.Contains("不達",s.TruceConfirmationView().Sent.Single().Status);Assert.Single(s.TruceConfirmationView().Reports);Assert.Empty(s.TruceConfirmationView().Sent.Single().Retryable);Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision).Code);}
    [Fact]public void AReceiptIsNotOpenableBeforeItsOwnPhysicalArrival(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var receipt=Receipt(s);Assert.Equal(ResultCode.NotAvailable,s.Open(Old,new(receipt.Id),s.Revision).Code);Assert.Empty(s.TruceConfirmationView().Reports);}
    [Fact]public void FailureRelayDoesNotMakeTheOpponentKnowAnUndeliveredConfirmation(){var s=Start();var p=Send(s);FailAndReport(s,p);Assert.Empty(TruceNegotiations.Known(s.DiagnosticSnapshot(),Opponent));Assert.False(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Other,Owner,s.Seconds,s.Revision));Assert.True(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Owner,Other,s.Seconds,s.Revision));}
    [Fact]public void AResendCannotBorrowALaterSameSecondOpeningOfTheFailureRelay(){var s=Start();var p=Send(s);var notice=FailAndReport(s,p,false);long before=s.Revision;Good(s.Open(Old,new(notice.Id),s.Revision));Good(s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision));var w=s.DiagnosticSnapshot();var e=w.TruceConfirmations!.Entries[^1];w.TruceConfirmations.Entries[^1]=e with{Revision=before+1};var copy=w.TruceConfirmations.Papers.Last();var forged=copy with{Revision=before+1,Authority=copy.Authority! with{Revision=before}};w.TruceConfirmations.Papers[^1]=forged;w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==forged.Id?m with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(forged))}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void AChangedSignerCannotResendUnderItsOldPoliticalAuthority(){var s=Start();var p=Send(s);FailAndReport(s,p);var b=s.HouseholdServiceView()!.Releases.Single(b=>b.Subject==Heir);Good(s.ManageHouseholdService(new(new("request:confirmation-release-old-bond"),HouseholdServiceAction.Release,Owner,b.Other,b.Source),Old,s.Revision));Good(s.ManageHouseholdService(new(new("request:confirmation-pledge-back"),HouseholdServiceAction.Pledge,Owner,Heir),Old,s.Revision));var id=new EntityId("request:confirmation-second-succession");Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Old),Old,s.Revision));Good(s.ManageHouseSuccession(new(new("request:confirmation-second-consent"),HouseSuccessionAction.Confirm,Owner,Original:id),Old,s.Revision));At(s,s.Seconds+1);Assert.Equal(Old,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));Assert.Equal(ResultCode.NotAvailable,s.SendTruceConfirmation(Input(s,TruceConfirmationAction.Resend,p.Id),Old,s.Revision).Code);Assert.Equal(Heir,s.DiagnosticSnapshot().TruceConfirmations!.Papers.First().Authority!.Issuer);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void LateRecoveredConfirmationAfterExpiryDoesNotRenewNonaggression(){var s=Start();var p=Send(s);FailAndReport(s,p);At(s,p.Terms.Until+1);s.DiagnosticRecoverLocalCourier(p.Id,1);At(s,s.Seconds+1);Assert.Single(TruceNegotiations.Known(s.DiagnosticSnapshot(),Opponent));Assert.False(TruceNegotiations.WillNotInitiate(s.DiagnosticSnapshot(),Other,Owner,s.Seconds,s.Revision));Assert.Equal(p.Terms,s.DiagnosticSnapshot().Truces!.Formations.Single().Terms);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void LostReceiptKeepsRequesterUninformedWithoutInventingFailureOfTheConfirmation(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var receipt=Receipt(s);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,receipt.Id));At(s,Arrival(s,receipt.Id)+2);Assert.Empty(s.TruceConfirmationView().Reports);Assert.Contains("未確認",s.TruceConfirmationView().Sent.Single().Status);Assert.Empty(s.TruceConfirmationView().Sent.Single().Retryable);new WorldSession(s.DiagnosticSnapshot());}

    static void FailReportAndWaitForSender(WorldSession s,TruceConfirmationPaper p){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,p.Id));At(s,Arrival(s,p.Id));var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id));At(s,Arrival(s,f.Id));}
    static TruceConfirmationPaper ReceiptRetry(WorldSession s){var p=Send(s);At(s,Arrival(s,p.Id));var receipt=Receipt(s);FailReportAndWaitForSender(s,receipt);return s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Receipt);}
    [Fact]public void ReceiptCopyWaitsForActualSenderFailureRecognitionAndKeepsOriginalObservation(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var receipt=Receipt(s);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,receipt.Id));At(s,Arrival(s,receipt.Id));Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,p=>p.Kind==TruceConfirmationKind.Receipt);var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==receipt.Id));At(s,Arrival(s,f.Id)-1);Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,p=>p.Kind==TruceConfirmationKind.Receipt);At(s,Arrival(s,f.Id));var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Receipt);Assert.Equal(receipt.Id,copy.CopyOf);Assert.Equal(receipt.ObservedAt,copy.ObservedAt);Assert.Equal(receipt.Evidence,copy.Evidence);Assert.Equal(receipt.Terms,copy.Terms);Assert.Equal(receipt.Authority,copy.Authority);At(s,Arrival(s,copy.Id));Assert.Empty(s.TruceConfirmationView().Reports);Good(s.Open(Old,new(copy.Id),s.Revision));Assert.Contains("返報を確認",s.TruceConfirmationView().Sent.Single().Status);Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Entries);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ReceiptCopiesStopAfterThreeEvenWhenEveryReturnIsLost(){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var original=Receipt(s);var latest=original;for(int i=0;i<3;i++){FailReportAndWaitForSender(s,latest);latest=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Receipt);}var copies=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Where(p=>p.Kind==TruceConfirmationKind.Receipt).ToArray();Assert.Equal(3,copies.Length);Assert.All(copies,c=>{Assert.Equal(original.ObservedAt,c.ObservedAt);Assert.Equal(original.Evidence,c.Evidence);Assert.Equal(original.Recipient,c.Recipient);});Assert.Empty(s.TruceConfirmationView().Reports);Assert.Single(s.DiagnosticSnapshot().Truces!.Fulfillments,f=>f.Actor==Opponent);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void FailureNoticeCopiesAlsoStopAtThreeWithoutRenewingConfirmation(){var s=Start();var p=Send(s);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,p.Id));At(s,Arrival(s,p.Id));var f=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Kind=="delivery-failure"&&s.DiagnosticSnapshot().Messaging.Attempts.Any(a=>a.Id==m.Body&&a.MessageId==p.Id));At(s,Arrival(s,f.Id));var original=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Single(p=>p.Kind==TruceConfirmationKind.FailureNotice);var latest=original;for(int i=0;i<3;i++){FailReportAndWaitForSender(s,latest);latest=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.FailureNotice);}var copies=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Where(p=>p.Kind==TruceConfirmationKind.FailureNotice).ToArray();Assert.Equal(3,copies.Length);Assert.All(copies,c=>{Assert.Equal(original.ObservedAt,c.ObservedAt);Assert.Equal(original.Evidence,c.Evidence);Assert.Equal(original.Related,c.Related);Assert.Null(c.Authority);});Assert.Single(s.DiagnosticSnapshot().TruceConfirmations!.Papers,p=>p.Kind==TruceConfirmationKind.Confirmation);Assert.Empty(s.TruceConfirmationView().Sent.Single().Retryable);new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ForgedFactualCopyCannotAlterObservationRecipientEvidenceOrAuthority(int n){var s=Start();var copy=ReceiptRetry(s);var w=s.DiagnosticSnapshot();var forged=n switch{0=>copy with{ObservedAt=copy.ObservedAt+1},1=>copy with{Recipient=Heir},2=>copy with{Evidence="message:forged-observation"},_=>copy with{Authority=copy.Authority! with{Issuer=Heir}}};w.TruceConfirmations!.Papers[^1]=forged;w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==copy.Id?m with{Body=System.Text.Encoding.UTF8.GetString(ContractJson.Write(forged)),RecipientId=forged.Recipient.Value}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void ReportCopiesAreFactualAndDoNotInventNewUserActions(){var s=Start();var copy=ReceiptRetry(s);var w=s.DiagnosticSnapshot();Assert.Equal(Opponent,copy.Sender);Assert.Equal(Old,copy.Requester);Assert.Single(w.TruceConfirmations!.Entries);Assert.All(w.TruceConfirmations.Entries,e=>Assert.Equal(Old,e.Actor));var original=w.TruceConfirmations.Papers.First(p=>p.Kind==TruceConfirmationKind.Receipt);Assert.Equal(original.Authority,copy.Authority);Assert.True(copy.At>copy.ObservedAt);Assert.True(copy.Revision>original.Revision);new WorldSession(w);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ReportRetryGenerationRecoveryAndFutureKeepTheSameObservation(int phase){var s=Start();var p=Send(s);At(s,Arrival(s,p.Id));var receipt=Receipt(s);if(phase==0){s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,receipt.Id));At(s,Arrival(s,receipt.Id));}else{FailReportAndWaitForSender(s,receipt);var copy=s.DiagnosticSnapshot().TruceConfirmations!.Papers.Last(p=>p.Kind==TruceConfirmationKind.Receipt);if(phase>=2){At(s,Arrival(s,copy.Id));if(phase==3)Good(s.Open(Old,new(copy.Id),s.Revision));}}Save(s,"truce-report-retry-"+phase);}
